mapper.insert:
INSERT INTO exam_question_group (
    group_type, title, instruction, content, shared_options, source_id, difficulty,
    knowledge_points, content_fingerprint, review_status, enabled
) VALUES (
    #{groupType}, #{title}, #{instruction}, #{content}, #{sharedOptions}, #{sourceId}, #{difficulty},
    #{knowledgePoints}, #{contentFingerprint}, #{reviewStatus}, #{enabled}
)

INSERT INTO exam_question (
    group_id, question_type, stem, options, correct_answer, explanation, reference_answer,
    sample_answer, scoring_rubric, source_id, group_sort_order, difficulty, knowledge_points,
    content_fingerprint, review_status, enabled
) VALUES (
    #{groupId}, #{questionType}, #{stem}, #{options}, #{correctAnswer}, #{explanation}, #{referenceAnswer},
    #{sampleAnswer}, #{scoringRubric}, #{sourceId}, #{groupSortOrder}, #{difficulty}, #{knowledgePoints},
    #{contentFingerprint}, #{reviewStatus}, #{enabled}
)

mapper.update:
UPDATE exam_question_group
SET review_status = #{reviewStatus}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{groupId}

UPDATE exam_question
SET review_status = #{reviewStatus}, updated_at = CURRENT_TIMESTAMP(3)
WHERE group_id = #{groupId}

UPDATE exam_question
SET review_status = #{reviewStatus}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}

UPDATE exam_question_group
SET enabled = #{enabled}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{groupId}

UPDATE exam_question
SET enabled = #{enabled}, updated_at = CURRENT_TIMESTAMP(3)
WHERE group_id = #{groupId}

UPDATE exam_question
SET enabled = #{enabled}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM exam_paper_item_snapshot
WHERE original_question_id = #{id}

mapper.delete:
DELETE FROM exam_question
WHERE id = #{id}
  AND NOT EXISTS (
      SELECT 1
      FROM exam_paper_item_snapshot
      WHERE original_question_id = #{id}
  )
